import{_ as o,C as t,o as s,c as a,E as r,a2 as c}from"./chunks/framework.BOeh4kYD.js";const d="/joinwell52/assets/authority-scope-20260910/03-recovery-budget.figure.en.png",b=JSON.parse('{"title":"Three Recoveries in Five Minutes—Until Recovery Erases the Counter","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Three Recoveries in Five Minutes—Until Recovery Erases the Counter","date":"2026-09-10","published_date":"2026-09-10","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Three Recoveries in Five Minutes—Until Recovery Erases the Counter","summary":"An Orca module experiment shows how a recovery mechanism can discard the evidence that its own limit depends on.","cover":"/assets/authority-scope-20260910/03-recovery-budget.cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Bounded pinned-source seam experiments; not full-system validation","pageClass":"authority-scope-article"},"headers":[],"relativePath":"en/engineering/2026-09-10-recovery-budget.md","filePath":"en/engineering/2026-09-10-recovery-budget.md","lastUpdated":1789010602000}'),h={name:"en/engineering/2026-09-10-recovery-budget.md"};function l(u,e,p,g,m,v){const i=t("ArticleCover"),n=t("ArticleTableScroll");return s(),a("div",null,[r(i,{image:"/assets/authority-scope-20260910/03-recovery-budget.cover-v1.png",kicker:"Open-source Engineering · Experiments",title:"Three Recoveries in Five Minutes—Until Recovery Erases the Counter",summary:"An Orca module experiment shows how a recovery mechanism can discard the evidence that its own limit depends on.",version:"2026-09-10",languageHref:"/zh/engineering/2026-09-10-recovery-budget",languageLabel:"中文"}),r(n,{language:"en"}),e[0]||(e[0]=c('<h1 id="three-recoveries-in-five-minutes—until-recovery-erases-the-counter" tabindex="-1">Three Recoveries in Five Minutes—Until Recovery Erases the Counter <a class="header-anchor" href="#three-recoveries-in-five-minutes—until-recovery-erases-the-counter" aria-label="Permalink to &quot;Three Recoveries in Five Minutes—Until Recovery Erases the Counter&quot;">​</a></h1><p>A terminal display stops responding while its backing process remains alive. Rebuilding the display and reconnecting to that process can restore useful work. To prevent recovery itself from looping, the application adds a cooldown and a limit of three recoveries per tab in five minutes.</p><p>The protection appears complete: a counter, a time window and cleanup after disposal. But cleanup can delete the timestamp written by the recovery that just succeeded. The next request then finds a fresh budget.</p><h2 id="two-indexes-disagree-about-one-object" tabindex="-1">Two indexes disagree about one object <a class="header-anchor" href="#two-indexes-disagree-about-one-object" aria-label="Permalink to &quot;Two indexes disagree about one object&quot;">​</a></h2><p>Orca is a desktop tool for organizing terminals and Agent work. <a href="https://github.com/stablyai/orca/pull/19745" target="_blank" rel="noreferrer">PR #19745</a> describes a Windows crash in which eight tabs reportedly remounted 8,878 times in roughly 122.4 seconds. We did not obtain the original crash bundle; those numbers are the author&#39;s incident report, not our measurements.</p><p>The public code exposes a mechanism worth testing. Terminal rows live in one index, while unified UI tabs live in another. They usually correspond but can diverge.</p><p>Remounting consults the terminal-row index. The old budget-release path consulted the unified UI index instead. The same tab could consequently receive two incompatible answers: it existed for the function performing a remount, but appeared absent to the cleanup function deciding whether to erase its recovery history.</p><p>Each lookup returned a definite answer. Their combination allowed recovery to discard the evidence of its own activity.</p><h2 id="test-the-causal-path-without-claiming-a-desktop-reproduction" tabindex="-1">Test the causal path without claiming a desktop reproduction <a class="header-anchor" href="#test-the-causal-path-without-claiming-a-desktop-reproduction" aria-label="Permalink to &quot;Test the causal path without claiming a desktop reproduction&quot;">​</a></h2><p>We pinned the base and proposed head revisions and loaded the complete recovery and lookup modules. The original budget calculation, instance disposal, remount and generation-update logic remained intact. We supplied fixtures for store plumbing, time, timers, PTY and logging. We did not start Electron or reproduce graphics-memory exhaustion.</p><p>Each cycle registered an instance, requested recovery and unregistered it. We then made the UI index miss a tab whose terminal row remained present. Two request schedules tested different constraints: 10 milliseconds between calls for the cooldown, and 16 seconds to move past the cooldown while remaining inside the cumulative budget window.</p><table tabindex="0"><thead><tr><th>Scenario</th><th style="text-align:right;">Requests</th><th style="text-align:right;">Base remounts</th><th style="text-align:right;">Proposed-head remounts</th></tr></thead><tbody><tr><td>Both indexes agree; 10ms spacing</td><td style="text-align:right;">200</td><td style="text-align:right;">1</td><td style="text-align:right;">1</td></tr><tr><td>Terminal row present, UI entry absent; 10ms spacing</td><td style="text-align:right;">200</td><td style="text-align:right;">200</td><td style="text-align:right;">1</td></tr><tr><td>Same divergence; 16s spacing</td><td style="text-align:right;">10</td><td style="text-align:right;">10</td><td style="text-align:right;">3</td></tr></tbody></table><p>Both rounds agreed. The first row shows that the old limiter was not universally ineffective. It worked when disposal could still see the tab. The second demonstrates history being reset under index divergence. The third separates the cumulative cap from the cooldown: even with requests spaced apart, the old code never retained enough history to reach its limit.</p><p><img src="'+d+'" alt="Remount counts under divergent indexes"></p><p><em>Figure 1. These counts describe successful remounts in the fixture&#39;s in-memory store, not production crashes. Source: saved rounds 1 and 2 of our pinned-source experiments.</em></p><h2 id="share-the-predicate-not-another-counter" tabindex="-1">Share the predicate, not another counter <a class="header-anchor" href="#share-the-predicate-not-another-counter" aria-label="Permalink to &quot;Share the predicate, not another counter&quot;">​</a></h2><p>The proposed fix does not lower the cap or introduce a second limiter. It makes the question “can this terminal still be remounted?” and the question “has this terminal gone away?” rely on the same terminal-row lookup.</p><p>Replacing a display instance does not end the lifetime of the terminal object that owns the recovery budget. If that object can still produce another recovery effect, a missing entry in a different UI projection should not erase the history constraining it.</p><p>This is a bounded correction. The two indexes can still disagree elsewhere. The patch chooses the appropriate source of identity for this budget; it does not establish system-wide index consistency.</p><h2 id="verify-legitimate-recovery-still-works" tabindex="-1">Verify legitimate recovery still works <a class="header-anchor" href="#verify-legitimate-recovery-still-works" aria-label="Permalink to &quot;Verify legitimate recovery still works&quot;">​</a></h2><p>Merely proving that a storm stops is insufficient: disabling every recovery would also satisfy that test. We retained three controls.</p><table tabindex="0"><thead><tr><th>Control</th><th>Result on both revisions</th></tr></thead><tbody><tr><td>Fixture removes the terminal row, disposes the instance, then recreates the same ID</td><td>Two requests produce two remounts</td></tr><tr><td>Requests at 0, 16, 32, 48 and 300.001 seconds</td><td>First three accepted, fourth constrained, final request accepted: four remounts</td></tr><tr><td>Replay the old generation after one successful recovery</td><td>Two requests produce one remount</td></tr></tbody></table><p>The close control mutates the fixture&#39;s terminal rows; it is not a real UI close action. It checks the budget-release branch. The expiry control checks that the cap does not become permanent, while the stale-generation control checks that delayed requests cannot continue acting on a replaced display instance.</p><p>Together, these controls distinguish preserving necessary history from freezing recovery altogether.</p><h2 id="a-budget-depends-on-evidence-surviving-cleanup" tabindex="-1">A budget depends on evidence surviving cleanup <a class="header-anchor" href="#a-budget-depends-on-evidence-surviving-cleanup" aria-label="Permalink to &quot;A budget depends on evidence surviving cleanup&quot;">​</a></h2><p>The tempting response to a recovery storm is another limit. This case suggests inspecting the existing limit&#39;s release conditions first. Who can erase its history? Does that decision rely on the object performing the action, or on a UI projection or cache that can temporarily lose sight of it?</p><p>The same question applies to retry counts, failure lockouts and spending budgets. An accurate timestamp is ineffective if the action&#39;s own cleanup path deletes it before the next admission decision.</p><p>Not every budget needs permanent persistence. Its lifetime does, however, need to cover the object it constrains, and its release predicate needs to agree with the execution predicate. The disappearance of a UI instance does not necessarily end a backing object&#39;s history.</p><p>The reusable finding is simple: <strong>a protection mechanism must both record an action correctly and preserve that record until the next decision that depends on it.</strong> Cleanup deserves the same scrutiny as admission.</p><p><a href="/joinwell52/zh/engineering/2026-09-10-recovery-budget">中文</a> · <a href="/joinwell52/en/research/evidence/2026-09-10-authority-scope">Methods, pinned revisions and raw results</a></p>',30))])}const f=o(h,[["render",l]]);export{b as __pageData,f as default};
